  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (117::BIGINT, 'En sí las clases son aburridas por la naturaleza del curso. Muchas veces las clases fueron asincrónicas y dejaba trabajos para la otra semana. También deja bastantes asignaciones, pero son cortas. Si se consigue un buen grupo pasa fácil. Es estricta con la rúbrica de evaluación.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-06-21T00:00:00+00:00'::TIMESTAMPTZ, '75f50623642028c21b32add0741ab727d6d2e98ff6d302b059cbe51ad6c52f5a'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Es buena profe, Es muy ordenada a lo largo del curso. Es importante seguir bien las instrucciones de las asignaciones, sino baja muchos puntos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '7450c1a5e985f7b6bd86cbd67687a273ca90fb2bdf13cb6de799c33fb63bd7a9'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Enfoca el seminario al tema ambiental. Creo que es de las mejores profes para este tipo de curso, pues no se torna muy pesado. Son 3 películas, dos reportes grupales de lecturas, 2 avances del proyecto y la entrega final de proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'dbf88e43d871514ba221fbba88c87b9388c35ce1c610f4aa25f59448113e5818'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Es una teja la profe, la verdad hace el curso chill y no deja muchos trabajos. Eso sí el proyecto final vale 50% de la nota, entonces consiga un buen grupo de trabajo, porque todo es grupal. Y siga la rúbrica que ella da para los trabajos al pie de la letra, porque ella califica justo con la rubrica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '3744f37cb5402242bc7095d2c5ebce7deaf70142df4dd13432338f4dc2e823eb'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Excelente persona, excelente profe. Entiende perfectamente el papel que tienen este tipo de cursos en el TEC , haciendo así que la clase sea entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '91a3021e8b467fe72b26d4046cf7fbc7b04a2f6bfb4ceda457d9d267e10ffe87'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'La profe es muy linda y buena gente. Las evaluaciones son cortas y tienen una rúbrica muy clara. En general el curso es muy bonito y la profe sabe muy bien cómo abarcar cada tema para que uno entienda. Es una excelente opción, va a ser un curso sencillo y bastante disfrutable con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '5c2d36627c1dc0abdef03d25489ba07d39de9de62bc7f4fa1cb06195442b04aa'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Excelente profe, enfoca el curso al medio ambiente, evaluaciones con rubricas claras, las clases se pasan rápido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'd62d1dd5899ce21672e5e25a11ee1410bbb6f03cc303ae4a8bfb3eeb52b60e84'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Excelente profesora, no dudaría en llevar otro curso con ella otra vez, las evaluaciones muy claras y sencillas (La mitad es una investigación, la otra mitad trabajos cortos), Las clases eran muy interesantes solo hay que ir a escuchar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '1f12d9210b547755f90f92a00db6cc9d9292521893e7f5a18fff1c27e8f57b1a'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Excelente profesora, las clases no son clases en sí son como un repaso de la materia de la semana lo que lo vuelve súper útil, muchos trabajos en grupo, pero son fáciles. Una vibra muy linda lo que hace que la clase fluya mucho. Solo 2 exámenes sencillos y que la verdad para el curso ni se necesitan'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bdab1dfd16c2c650945d4b0f74d035f7525902325e78829ff591500c85b7f475'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Las clases no son clases basicamente. Los temas están muy relacionados para que la profe de ejemplos reales dentro del TEC, por lo que no hace la clase tan aburrida. Las evaluaciones son sencillas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '22bbf1215dc10d0e032d7f83c8646f71350ad3ba435873d0d92094e322384255'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'La clase no sirve para nada, es como un momento para hablar y chismear con la profe; los trabajos son fáciles y el curso se pasa super bien. Se agardece que el curso no sea pesado considerando sus créditos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, '308ea2fb576cd8e321f0809f309a518e7dda15d4271fc9ddfd6181bd89863506'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'El curso lo enfocó a la ecología de CR, tiene algunas partes interesantes y otras aburridas. El curso fueron puros trabajos grupales sencillos. Aunque ya en presencial puede que la investigación requiera movilizarse a la zona estudiada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a2517ba8833078e10f55a0d58692326368fa05ede114ad3a79ef33f032a750e2'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Queridos estudiantes que piensan matricular con ella, les cuento mi experiencia: No fui a ninguna clase y pasé el curso con 90, las clases son sumamente inútiles para la realización de los trabajos, perfectamente se pueden hacer sin ir a clases.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4343a3b0bdb917af0783768abeba16a4297e244a51a6fe5048845c4980e6228d'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Es unha mierda de profesora, juega de importante y las dudas las cubre solo por correo y tras de todo es exigente, entonces es una mierda poder preguntarle, no matricularia mas con esa profesora, de las profesoras mas malas que hay en él TEC pata mi sin duda alguna'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '057de1b2306bfd3be1471243bd8cc33c12c2ef9f78fd45d1c0347df49537c212'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'El curso se pasa muy fácil con esta profesora. Solo hay como dos clases sincrónicas en el semestre, todo lo demás es asíncrónico así que es muy provechoso. Deja mucha tareas grupales o en pareja a la semana pero no es nada del otro mundo. Eso sí, califica duro. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ab503cd61ca806861cd27256a289706495d19f75ddbee4f2223c6fd097d17b04'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Todas las clases son asincrónicas, no nos quiso revisar un trabajo para corregirlo antes de entregarlo, baja puntos por la cosa más mínima, eviten a esta profesora'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'c7aca884592d6abf5e2fa9c55a57d775276c2f39ef5674607cc5756a1bebc37a'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Si trabaja esta es su profesora porque no hay que asistir a ninguna clase, sus trabajos no son largos ni difíciles, con que todos los compañeros de su grupo aporten un poco pueden pasar el curso sin problemas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '877b7523d9ed18bd1283e6db9712090cc4e9f130e28df4fe764c285b0d82e6dd'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Todas las clases son asincronicas, deja lecturas super largas y todos los trabajos son en grupo. Es difícil entender lo que quiere en el trabajo de investigación, la rubrica es rara.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, '67e52c9b0441ba80a3ac1375e75ed760f0f7644d140513a2a9559c7ab6615a40'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-10T00:00:00+00:00'::TIMESTAMPTZ, '601c035d5395970844e82e347ee8686e3e9a1e328e1144d04d9fb7e29ffe2737'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Todo asincrónico. Los trabajos es grupo con ella son raros. Trabaje uno más que el otro y aunque uno le diga dice que no importa, que todos deberán recibir la misma calificación.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2021-02-28T00:00:00+00:00'::TIMESTAMPTZ, '5921053e83108154a46492280b99a4a054d5abce907d84676e898a980626a9c1'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'El curso es asincrónico, y la profe ni aparece prácticamente se da solo. Es sumamente estricta para calificar ya que baja puntos por todo y responde las consultas tarde. No la recomiendo para nada...'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '29609dd5ca5b8a5dc0e9078844c133f2f4ce48003ec48900c36d45a1a427e1cf'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Curso totalmente asíncrono, pero ella no da instrucciones demasiado claras, trabajo casi todas las semanas en grupo, muuuchos cineforos de películas un poco inusuales, pero si usted le pregunta a la profe, ojalá por zoom, la compa es un amor. El seminario es sobre Ecología'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '95721e3065315926ca29953ecff9cb88b86aa88cd6838713b333eb1e3ac050d8'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Si usted sigue lo que dice la rúbrica, le va bien. Los trabajos son cortos y no deja para todas las semanas. Realmente me gustó llevar el curso con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'd299e4c14e23f31cb939384ca733b80dcb31501ee7aae6d7adaed09b3dc39c29'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Es muy estricta evaluando, por lo que tiene que hacer los trabajos acorde con el criterio de evaluación que ella provee. Coordine bien con su pareja/grupo para ablandar la carga de trabajo (por favor haga su parte con tiempo)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f0a3e0d79f03ed3c7cf4171e25d131e215a86fd7a139a41af2a266e2fd5ab5e8'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'No hay clase sincrónica en todo el semestre. Califica duro y es terca con la calificación. Deja muchos trabajos para ser un curso de pocos créditos. Mucha gente salió con malos promedios porque pide una investigación super profunda y nunca dió clase, además solo manda instrucciones por escrito.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'd5b802cc3323fd92f737cd74f77da8b6695c8377163c994a72b103e389692abe'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Gente, no les crean a todos esos comentarios porque son clickbait o algo. Estoy llevando con ella clases virtuales en medio de la pandemia y las clases son asincrónica y deja bastantes trabajos, muchos son simples pero los trabajos escritos son enormes y califica rudisimo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'efffbb8e1e7025445ece7f19e80546b7ab3e45f9a1381608400117934295beb8'::TEXT, ARRAY[981]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'b8650e16b113d0fee88965e40abcd4c2c9462fd58b9575fff62e59d1d52d3ed6'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Esta formación humanística fue la más aburrida que llevé y da mucha vergüenza la exposición final, por otro lado uno puede distraerse con cualquier cosa tranquilamente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'e3255c39c75c2e16baaafa2ff9fd8a8ac83d6cdfb4777ab1ef8fa627738eec45'::TEXT, ARRAY[867]::BIGINT[]),
    (117::BIGINT, 'Para un curso aburrido ella hace que no lo sea, es muy vacilona y muy linda persona. Ayuda mucho en los examenes y son grupales. SOn muy faciles y aunque no haga nada y solo copie los esquemas pasa facil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '341151479848496b3eb64cb06058c819d1d2c32e8ce34602920ae52d95e06f5b'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Las clases con ella se hacen entretenidas y vacilonas. Muy buena profe en general y muy linda persona. La recomiendo al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '72db813074524da8e880a31409b81bbb44a17d5ef8b1f6dce1808412d8dc887c'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Sus exámenes son complicados, sin embargo es una excelente profesora y si le pone pasa muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '6ed5840294ea36bcda3c2721a2e20f440e6f1d76b46405131d6c84bdc0fa2857'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Muy fácil salir bien con ella, es muy cómica y las clases nunca son aburridas. No hay exámenes pero sí que una que otra tarea fácil. Super recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Clases excelentes']::TEXT[], '2018-12-25T00:00:00+00:00'::TIMESTAMPTZ, '28b36ee28da94f3681187f2eefc1c451356d2d6318ce22ccd3fec1153a4b1eeb'::TEXT, ARRAY[1004]::BIGINT[]),
