    (117::BIGINT, 'La clase es muy divertida y no se hace nada que demande mucho tiempo, solo un par de foros. Los exámenes son en grupo o parejas y a pesar de todo uno se siente preparado para el examen colegiado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '4bd6a5473d6b744f42e979f1d8b320e6d5f94916afa907c4b5a32fd8a95acaf9'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'se pasa facil y las clases son divertidas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '34ff39e5f144964cb9a1eb3e9c94f0942ca4d2b3779bed558e21516c2b3f3b3d'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Sin duda alguna una de las mejores profesoras que he tenido, explica todo MUY claro y además de forma divertida, hace que las clases se pasen rápido y además califica suave, si puede meter con ella no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-16T00:00:00+00:00'::TIMESTAMPTZ, '2010f46aec7e4e533a69a15d3b6c1c3b0baabd0fbb68d509c8af8f8691e494b3'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Clases divertidas, trabajos y exámenes fáciles; 2 créditos con 95 fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '17e5164f680bb64e147a90c6d066ff49eb6f08b6b3098f0d3fd154e8aa8e885a'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ba31cd3ad8e484a9f1ea57d93534f12a02f911ecf711c22a4652f5d1296b8247'::TEXT, ARRAY[1004]::BIGINT[]),
    (117::BIGINT, 'Demasiado fácil y la profe es muy tuanis, se pasa super fácil, inclusive se aprende cultura general.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd25ef702b078a2cd5d19385bcd14414dac6a15e149c75ce624ed2b29afa36471'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Trata de ayudar al estudiante en lo posible, ayuda demasiado y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd9acb29881c58faa5b02d09594497c041081042d945dd4cfa7df1e763f646ad9'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Ella sabe que el curso es de relleno, se pasa fácil y las clases son entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '70650022c927b26e627cc3d08366469f000e1daa06ddc46079c87e6315f88a15'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Es un buena profe, hace las clases cortar y califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '01525854a5966f61d0e489bbad002b31e9b706812a74bd7c5d5aa995d8da950b'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Se desvía de los temas de clase. Es estricta con los lineamientos que establece en los trabajos, pero en realidad se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'dc19bfe55a61c37853916eced11fd50462cb73ed742ad1b56a37b476dee2f195'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a4f528d36a396a8fd55202f156f6266bf81cecb3b670bb5e31ce9146755ec47b'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Se pierden muchas clases, no explica la materia, habla por horas y no se aprende, se pasa muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8b75b591fbf7fb6256d3d62c3f4d3c47cb8bd4882f7a8561c4e784d1596f65ad'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Para el curso que es, bastante buena, hace la clase entretenida y los trabajos son bastante faciles.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2acea0cc4b6f945790f41759370d54374c9ee1de7a0fe115bd81323567a325f2'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Muy fácil. Deja muchas lecturas y en la clase no explica nada, pero califica suave. No muchos trabajos y los examenes son faciles.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'a6fefc08dcc231b90795bf7605ec9d4aafceb9fe0c8ce5b02e4ce8222dafe770'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Yo la verdad la recomiendo, lleve intro y la verdad nunca me leí ninguna lectura y pasé con 95 :) Los examenes son de escribir y escribir pero pura hablada :p nada complicado, los unicos trabajos que deja son cineforos, es demasiado facil, jaja pero si quiere aprender algo ella no es la indicada.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '87b881979ce8b15774a3976092e32c041e6f1abb5945f2fbaa30fc68daa7c494'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b87184d8b26f338e987aa79ebf2cf878a159852e211cf46c3a18e4d4e7b1c5c9'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Con ella se aprende de todo un poco, en sus clases se hablan de todos los temas, uno siente que no aprendió nada, pero en realidad si se aprende, de las lecturas si no aprendes nada, oero aprendes cosas "interesantes de la vida" En sus examenes solo escribir mucho y califica muy suave.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c9eb2e8f5c54daa29874c091bab6d9bea2ace8b9c673f8a809ad5d3867510e4e'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Excelente profe, los exámenes no son de saberse de memoria las lecturas sino más bien de ponerlas en práctica y son fáciles, los trabajos en clase son fáciles y en grupo, los cineforos no son cosa del otro mundo. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8f18ef190dd3a608d073738846dea19f0b9b477fefb5fa5fca0a7eb4d2baba95'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0c53f9744c713c274c3dbfd82781954a5fda2d07996d822bf3744c4d82f8a860'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'Buena profe, hace las clases muy divertidas. Si se hacen las lecturas respectivas y se trata de, los parciales son muy fáciles ya que nos son teoricos sinó como de poner en práctica el conocimiento.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'fb880f23deeb9e97ccbfe5438db459c37b61ec3e3a4cd16c2991ee3b1414b69e'::TEXT, ARRAY[559]::BIGINT[]),
    (117::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, '5433d99d5cf278dc612fda9e0e4b91cb4c2ff56c7687c8c7462e76522f1e0889'::TEXT, ARRAY[628]::BIGINT[]),
    (117::BIGINT, 'No explica nada, los examenes son muy duros'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'fbcebd2facf36c7beebb75b72fe90ee07fc538fae8d138819c007b60919c8352'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
